CREATE TABLE IF NOT EXISTS messenger_conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), page_id uuid NOT NULL REFERENCES facebook_pages(id), facebook_conversation_id text NOT NULL UNIQUE, participant_id text, participant_name text, last_message text, last_message_at timestamptz, last_customer_message_at timestamptz, unread boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS messenger_conversations_recent_idx ON messenger_conversations(last_message_at DESC);
CREATE TABLE IF NOT EXISTS messenger_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES messenger_conversations(id) ON DELETE CASCADE, facebook_message_id text NOT NULL UNIQUE, from_id text, from_name text, message text NOT NULL DEFAULT '', is_from_page boolean NOT NULL DEFAULT false, created_time timestamptz NOT NULL, sent_by text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS messenger_messages_thread_idx ON messenger_messages(conversation_id, created_time);
